// 古诗词 (classical poems) data API. Generated by scripts/convert_poems.py from
// sources/古诗词_作品总表.xlsx — never edit the JSON by hand.
// meta.json (~60 KB: eras, themes, imagery dictionary, list fields of every poem) drives the scroll,
// the theme/imagery views and search; each poem's full data (lines, glosses, analysis) is its own
// lazy chunk under poems/p/{slug}.json.

const loaders = import.meta.glob("./poems/p/*.json");

let _meta = null;
// { dynasties:[{key,py,en,years,intro,introEn}], themes:[{zh,en}],
//   imagery:[{zh,py,en,meaning,meaningEn,count}],
//   poems:[{id,slug,title,titlePy,titleEn,author,authorEn,dynasty,form,tune,level,themes:[],images:[],first,excerpt}] }
export function loadPoemsMeta() {
  return (_meta ??= import("./poems/meta.json").then((m) => m.default));
}

const _cache = new Map();
// full poem: list fields + { authorPy, intro, analysis, analysisEn, background, pronunciation, version, song,
//   lines:[{s (stanza), zh, rhythm, py, lit, en, tts?}], words:[{w,py,en,note}], imagery:[{name,zh,en}] }
export function loadPoem(slug) {
  if (_cache.has(slug)) return _cache.get(slug);
  const loader = loaders[`./poems/p/${slug}.json`];
  const p = loader ? loader().then((m) => m.default) : Promise.resolve(null);
  _cache.set(slug, p);
  return p;
}
